/* GymLog — per-exercise how-to notes + secondary muscles
   sec: secondary muscle groups (primary comes from the exercise's own `m` field) */

const EX_INFO = {
  /* ---------- Chest ---------- */
  'bb-bench': { sec: ['triceps', 'shoulders'], en: 'Lie flat, shoulder blades pulled back and down, feet planted. Lower the bar to mid-chest under control and press without letting the elbows flare past ~60°.', ru: 'Лягте на скамью, лопатки сведены и опущены, стопы упёрты в пол. Опускайте штангу к середине груди подконтрольно и жмите, не разводя локти шире ~60°.' },
  'bb-incline': { sec: ['triceps', 'shoulders'], en: 'Bench at 30°, not steeper — higher angles shift the load onto the front delts. Touch the upper chest, press in a slight arc back over the shoulders.', ru: 'Наклон скамьи 30°, не круче — больший угол переносит нагрузку на передние дельты. Касайтесь верха груди, жмите по небольшой дуге назад, к плечам.' },
  'db-bench': { sec: ['triceps', 'shoulders'], en: 'Dumbbells allow a natural wrist path and a deeper stretch than a bar. Lower until the elbows are just below the torso, press without clanging the bells together.', ru: 'Гантели дают естественную траекторию кисти и большую растяжку, чем штанга. Опускайте, пока локти не окажутся чуть ниже корпуса, вверху не стучите гантелями друг о друга.' },
  'db-incline': { sec: ['triceps', 'shoulders'], en: 'Bench at 30°. Keep the elbows slightly tucked and stop the descent when you feel the stretch — no forcing depth at the shoulder joint.', ru: 'Наклон 30°. Локти слегка прижаты, опускание останавливайте на ощущении растяжения — не продавливайте плечевой сустав ради глубины.' },
  'machine-press': { sec: ['triceps', 'shoulders'], en: 'Set the seat so the handles sit at mid-chest height. The fixed path makes this the safest heavy pressing option for a cranky shoulder.', ru: 'Отрегулируйте сиденье так, чтобы рукояти были на уровне середины груди. Фиксированная траектория делает это самым безопасным тяжёлым жимом для проблемного плеча.' },
  'pec-deck': { sec: ['shoulders'], en: 'Isolation for the chest — elbows slightly bent and locked at that angle throughout. Squeeze for a beat at the point of full contraction.', ru: 'Изоляция на грудь — локти чуть согнуты и зафиксированы в этом положении. В точке максимального сведения задержитесь на секунду.' },
  'cable-fly': { sec: ['shoulders'], en: 'Constant tension the whole range, unlike dumbbell flyes. Step forward slightly, lead with the elbows and bring the hands together in front of the sternum.', ru: 'Постоянное натяжение по всей амплитуде, в отличие от разводок с гантелями. Сделайте небольшой шаг вперёд, ведите движение локтями и сводите руки перед грудиной.' },
  'push-up': { sec: ['triceps', 'shoulders', 'core'], en: 'Body in one line from head to heels, hands slightly wider than the shoulders. Add load with a plate on the back or elevate the feet once bodyweight is easy.', ru: 'Тело в одну линию от головы до пяток, руки чуть шире плеч. Когда свой вес становится лёгким, добавьте блин на спину или поднимите ноги на возвышение.' },
  'chest-dip': { sec: ['triceps', 'shoulders'], en: 'Lean the torso forward ~30° to bias the chest. Stop when the upper arms reach parallel — going deeper stresses the shoulder capsule.', ru: 'Наклоните корпус вперёд примерно на 30°, чтобы нагрузить грудь. Останавливайтесь, когда плечо доходит до параллели — глубже нагружается капсула плечевого сустава.' },

  /* ---------- Back ---------- */
  'lat-pulldown': { sec: ['biceps', 'forearms'], en: 'Grip slightly wider than the shoulders. Pull the bar to the collarbone by driving the elbows down and back, chest up, no big backward lean.', ru: 'Хват чуть шире плеч. Тяните рукоять к ключицам, направляя локти вниз и назад, грудь раскрыта, без сильного отклонения корпуса назад.' },
  'pull-up': { sec: ['biceps', 'forearms', 'core'], en: 'Start from a dead hang, pull until the chin clears the bar, lower under control. Use a band or the assisted machine if you can\'t get 5 clean reps.', ru: 'Начинайте из полного виса, тянитесь, пока подбородок не окажется выше перекладины, опускайтесь подконтрольно. Если не выходит 5 чистых повторов — резина или гравитрон.' },
  'assisted-pullup': { sec: ['biceps', 'forearms'], en: 'The counterweight reduces your effective bodyweight, so a higher number on the stack means more help. Reduce the assistance as you get stronger.', ru: 'Противовес уменьшает ваш рабочий вес: чем больше вес на стеке, тем сильнее помощь. По мере прогресса уменьшайте помощь.' },
  'seated-row': { sec: ['biceps', 'forearms'], en: 'Chest tall, pull the handle to the navel, squeeze the shoulder blades together. Keep the lower back still — no rocking to move the weight.', ru: 'Грудь раскрыта, тяните рукоять к животу, сводя лопатки. Поясница неподвижна — не раскачивайтесь, чтобы сдвинуть вес.' },
  'cs-row': { sec: ['biceps', 'forearms'], en: 'The chest pad takes the lower back out of the movement — a good rowing option when the spine needs protecting. Pull elbows past the torso, pause, control the return.', ru: 'Упор в грудь выключает поясницу — хороший вариант тяги, когда нужно беречь спину. Проводите локти за корпус, пауза, подконтрольный возврат.' },
  'bb-row': { sec: ['biceps', 'forearms', 'hamstrings'], en: 'Hinge to ~45°, brace hard, pull to the lower ribs. The unsupported spine takes real load here — go lighter or pick a chest-supported row if your back is sensitive.', ru: 'Наклон около 45°, жёсткое напряжение корпуса, тяга к нижним рёбрам. Позвоночник без опоры реально нагружен — при чувствительной спине берите меньше веса или тягу с упором в грудь.' },
  'db-row': { sec: ['biceps', 'forearms'], en: 'One knee and hand on the bench, back flat. Pull the dumbbell to the hip, not to the shoulder, and let the shoulder blade travel at the bottom.', ru: 'Колено и рука на скамье, спина ровная. Тяните гантель к бедру, а не к плечу, внизу давайте лопатке уйти вперёд.' },
  't-bar-row': { sec: ['biceps', 'forearms'], en: 'Heavy mid-back work. Chest supported if the machine allows — the free-standing version loads the lower back the same way a barbell row does.', ru: 'Тяжёлая работа на середину спины. Если тренажёр позволяет — с упором в грудь; свободный вариант грузит поясницу так же, как тяга штанги.' },
  'sa-pulldown': { sec: [], en: 'Arms nearly straight the whole time — the movement happens at the shoulder, not the elbow. Isolates the lats without involving the biceps.', ru: 'Руки почти прямые всё движение — работает плечевой сустав, а не локтевой. Изолирует широчайшие, не подключая бицепс.' },
  'deadlift': { sec: ['hamstrings', 'glutes', 'forearms', 'core'], en: 'Maximum axial load of any lift. Bar over mid-foot, brace, push the floor away with a neutral spine. Skip it entirely if your back isn\'t cleared for loading.', ru: 'Максимальная осевая нагрузка среди всех упражнений. Гриф над серединой стопы, жёсткий корпус, отталкивайтесь от пола с нейтральной спиной. При непролеченной спине — не делать вообще.' },
  'rack-pull': { sec: ['glutes', 'forearms'], en: 'Deadlift from pins at or just below the knee — shorter range, less hip flexion, still heavy spinal loading.', ru: 'Становая с плинтов на уровне колена или чуть ниже — короче амплитуда, меньше сгибание в тазобедренном, но осевая нагрузка на позвоночник сохраняется.' },
  'db-shrug': { sec: ['forearms'], en: 'Straight up and down — rolling the shoulders adds nothing. Hold the top position for a second on each rep.', ru: 'Строго вверх-вниз — вращать плечами бессмысленно. В верхней точке задержка на секунду.' },

  /* ---------- Shoulders ---------- */
  'db-shoulder': { sec: ['triceps'], en: 'Seated with back support. Press from ear height to lockout without shrugging; dumbbells let the shoulders rotate naturally, unlike a barbell.', ru: 'Сидя с опорой на спинку. Жмите от уровня ушей до выпрямления рук без пожимания плечами; гантели, в отличие от штанги, позволяют плечу вращаться естественно.' },
  'bb-ohp': { sec: ['triceps', 'core'], en: 'The bar has to travel around the head, which forces shoulder extension and internal rotation — the position most likely to aggravate an irritated shoulder.', ru: 'Гриф вынужден идти вокруг головы, что требует разгибания и внутренней ротации плеча — самое рискованное положение для раздражённого плечевого сустава.' },
  'machine-shoulder': { sec: ['triceps'], en: 'The fixed path removes the balance demand and lets you push closer to failure safely. Set the seat so the handles start at shoulder height.', ru: 'Фиксированная траектория снимает задачу стабилизации и позволяет безопаснее работать до отказа. Настройте сиденье так, чтобы рукояти были на уровне плеч.' },
  'lateral-raise': { sec: [], en: 'Lead with the elbows, thumbs level or slightly down, stop at shoulder height. Light weight and strict form beat heavy swinging here.', ru: 'Ведите движение локтями, большие пальцы на уровне мизинцев или чуть ниже, останавливайтесь на уровне плеч. Малый вес и строгая техника лучше, чем тяжёлые махи с раскачкой.' },
  'cable-lateral': { sec: [], en: 'Same movement as the dumbbell version but with tension at the bottom, where dumbbells give none. Cable behind the back, one arm at a time.', ru: 'То же движение, что с гантелями, но с нагрузкой в нижней точке, где гантели её не дают. Трос за спиной, работайте по одной руке.' },
  'rear-delt-fly': { sec: ['back'], en: 'Bent over or chest-supported, elbows slightly bent, sweep the arms out and back. Directly balances all the pressing volume — worth including every week.', ru: 'В наклоне или с упором в скамью, локти слегка согнуты, разводите руки в стороны и назад. Прямо компенсирует объём жимов — стоит делать каждую неделю.' },
  'face-pull': { sec: ['back'], en: 'Rope at eye height, pull towards the forehead while rotating the hands outward. The best single exercise for shoulder health and posture.', ru: 'Канат на уровне глаз, тяните ко лбу, разворачивая кисти наружу. Лучшее одиночное упражнение для здоровья плеч и осанки.' },
  'front-raise': { sec: [], en: 'Front delts already get heavy work from every press — treat this as optional accessory volume, not a staple.', ru: 'Передние дельты и так получают нагрузку в каждом жиме — считайте это опциональной добавкой, а не основой.' },
  'upright-row': { sec: ['back', 'biceps'], en: 'Pulling the elbows high with a narrow grip forces shoulder impingement. If you do it at all, use a wide grip and stop below chest height.', ru: 'Высокий подъём локтей узким хватом провоцирует импинджмент плеча. Если делаете — широкий хват и остановка ниже уровня груди.' },

  /* ---------- Biceps ---------- */
  'bb-curl': { sec: ['forearms'], en: 'Elbows pinned to the sides, no swinging at the hips. An EZ bar is easier on the wrists than a straight bar.', ru: 'Локти прижаты к бокам, без раскачки в тазу. EZ-гриф щадит запястья сильнее прямого.' },
  'db-curl': { sec: ['forearms'], en: 'Supinate — rotate the palm up — as you lift; the biceps both bends the elbow and turns the forearm.', ru: 'Во время подъёма супинируйте кисть — разворачивайте ладонь вверх; бицепс и сгибает локоть, и разворачивает предплечье.' },
  'hammer-curl': { sec: ['forearms'], en: 'Neutral grip loads the brachialis and brachioradialis, which sit under and beside the biceps — this is what adds arm thickness.', ru: 'Нейтральный хват грузит брахиалис и брахиорадиалис, лежащие под бицепсом и рядом с ним, — именно они дают толщину руки.' },
  'incline-curl': { sec: ['forearms'], en: 'Lying back puts the biceps in a stretched position at the bottom, which is the hardest and most productive part of the range.', ru: 'Отклонение назад ставит бицепс в растянутое положение внизу — самая тяжёлая и самая продуктивная часть амплитуды.' },
  'preacher-curl': { sec: ['forearms'], en: 'The pad prevents any body English. Don\'t fully lock out at the bottom under a heavy load — it stresses the elbow tendon.', ru: 'Пюпитр исключает читинг корпусом. Не выпрямляйте руку полностью внизу с большим весом — это нагружает сухожилие локтя.' },
  'cable-curl': { sec: ['forearms'], en: 'Constant tension top to bottom. Good as the last biceps movement, where dumbbells start to feel weightless at the top.', ru: 'Постоянное натяжение сверху донизу. Хорош как завершающее упражнение на бицепс, где гантели в верхней точке уже почти невесомы.' },

  /* ---------- Triceps ---------- */
  'pushdown': { sec: [], en: 'Elbows locked at the sides, only the forearms move. Full extension at the bottom, controlled return.', ru: 'Локти зафиксированы у корпуса, движутся только предплечья. Внизу полное выпрямление, возврат подконтрольный.' },
  'rope-pushdown': { sec: [], en: 'Spread the rope apart at the bottom to finish the contraction. Slightly better lateral-head activation than a straight bar.', ru: 'Внизу разводите концы каната в стороны, завершая сокращение. Латеральный пучок включается чуть лучше, чем с прямой рукоятью.' },
  'oh-triceps': { sec: [], en: 'Overhead position stretches the long head, which the pushdown barely touches. Keep the elbows pointing forward, not flaring out.', ru: 'Положение над головой растягивает длинный пучок, который почти не работает в разгибаниях на блоке. Локти смотрят вперёд, не разъезжаются.' },
  'skullcrusher': { sec: [], en: 'Lower the bar behind the forehead, not to it, to keep tension on the triceps. Use an EZ bar and stop if the elbows complain.', ru: 'Опускайте гриф за голову, а не ко лбу, чтобы сохранить нагрузку на трицепс. Работайте с EZ-грифом и прекращайте, если локти дают о себе знать.' },
  'cg-bench': { sec: ['chest', 'shoulders'], en: 'Hands shoulder-width, elbows tucked, bar to the lower chest. Narrower than shoulder-width just wrecks the wrists without helping the triceps.', ru: 'Руки на ширине плеч, локти прижаты, гриф к низу груди. Уже плеч — только убивает запястья, не добавляя нагрузки на трицепс.' },
  'triceps-dip': { sec: ['chest', 'shoulders'], en: 'Torso upright — leaning forward turns it into a chest exercise. Stop at parallel to protect the shoulder.', ru: 'Корпус вертикально — наклон вперёд превращает движение в грудное. Останавливайтесь на параллели, чтобы беречь плечо.' },
  'bench-dip': { sec: ['shoulders'], en: 'Hands on the bench behind you, feet out front. Easy to load with a plate on the lap, but hard on the shoulder in the bottom position.', ru: 'Руки на скамье позади, ноги впереди. Легко нагрузить блином на бёдра, но нижняя точка тяжела для плеча.' },

  /* ---------- Quads ---------- */
  'leg-press': { sec: ['glutes', 'hamstrings'], en: 'Back and hips flat against the pad — this is what keeps the spine unloaded. Feet mid-platform, lower until the knees reach ~90°, never let the lower back round off the seat.', ru: 'Спина и таз плотно прижаты к спинке — именно это разгружает позвоночник. Стопы по центру платформы, опускайте до угла ~90° в колене, поясница не должна отрываться от сиденья.' },
  'hack-squat': { sec: ['glutes'], en: 'Back supported by the pad throughout, so the spine carries no free axial load. Feet mid-platform, descend under control, drive through the whole foot.', ru: 'Спина всё время на опоре, поэтому свободной осевой нагрузки на позвоночник нет. Стопы по центру платформы, опускайтесь подконтрольно, толкайтесь всей стопой.' },
  'machine-squat': { sec: ['glutes'], en: 'A squat pattern with the torso fixed — the safest way to train the movement when free-weight squats are off the table.', ru: 'Приседание с фиксированным корпусом — самый безопасный способ тренировать паттерн, когда свободные приседы противопоказаны.' },
  'back-squat': { sec: ['glutes', 'hamstrings', 'core'], en: 'The bar sits on the spine, so every kilo compresses it. Excellent lift in general, wrong lift when the back needs protecting.', ru: 'Штанга лежит на позвоночнике, и каждый килограмм сжимает его. Отличное упражнение в целом, но неподходящее, когда спину нужно беречь.' },
  'front-squat': { sec: ['glutes', 'core'], en: 'More upright than the back squat and more quad-dominant, but still a fully axial load on an unsupported spine.', ru: 'Корпус вертикальнее, чем в приседе со штангой на спине, акцент на квадрицепс сильнее, но осевая нагрузка на неподдержанный позвоночник остаётся.' },
  'goblet-squat': { sec: ['glutes', 'core'], en: 'Dumbbell held at the chest counterbalances you into an upright position. Light spinal load — a reasonable warm-up or low-load option.', ru: 'Гантель у груди работает противовесом и удерживает корпус вертикально. Осевая нагрузка невелика — подходит как разминка или лёгкий вариант.' },
  'leg-extension': { sec: [], en: 'Pure quad isolation with zero spinal load. Pause at the top; don\'t slam into full lockout with a heavy stack.', ru: 'Чистая изоляция квадрицепса без нагрузки на позвоночник. Пауза вверху; не выбрасывайте ногу в замок с большим весом.' },
  'bulgarian': { sec: ['glutes', 'hamstrings'], en: 'Rear foot elevated, front shin roughly vertical. Brutal for quads and glutes with far less spinal load than a barbell squat.', ru: 'Задняя нога на возвышении, голень передней ноги примерно вертикально. Жёстко нагружает квадрицепс и ягодицы при куда меньшей нагрузке на позвоночник, чем присед.' },
  'lunge': { sec: ['glutes', 'hamstrings'], en: 'Step out, drop the back knee towards the floor, push through the front heel. Dumbbells at the sides keep the load off the spine.', ru: 'Шаг вперёд, заднее колено опускается к полу, толчок через пятку передней ноги. Гантели по бокам не нагружают позвоночник.' },

  /* ---------- Hamstrings ---------- */
  'lying-leg-curl': { sec: ['calves'], en: 'Hips pressed into the pad; lifting them shortens the range and cheats the hamstrings. Control the negative — this is where the growth is.', ru: 'Таз прижат к подушке; если он отрывается, амплитуда укорачивается и бицепс бедра «обманывает». Контролируйте негативную фазу — рост именно там.' },
  'seated-leg-curl': { sec: ['calves'], en: 'The hip-flexed position stretches the hamstrings more than the lying version, and research favours it slightly for growth.', ru: 'Согнутое положение таза растягивает бицепс бедра сильнее, чем лёжа; данные говорят о небольшом преимуществе для роста.' },
  'db-rdl': { sec: ['glutes', 'back', 'forearms'], en: 'Hip hinge, not a squat: push the hips back with soft knees, dumbbells tracking the legs. Stop the moment the lower back starts to round — that\'s your range.', ru: 'Это шарнир в тазу, а не присед: таз уходит назад, колени мягкие, гантели скользят вдоль ног. Останавливайтесь в момент, когда поясница начинает круглиться — это ваша амплитуда.' },
  'bb-rdl': { sec: ['glutes', 'back', 'forearms'], en: 'Same pattern as the dumbbell version but the load sits further from the body, multiplying the shear force on the lower back.', ru: 'Тот же паттерн, что с гантелями, но вес дальше от тела, что увеличивает сдвиговую нагрузку на поясницу.' },
  'good-morning': { sec: ['glutes', 'back'], en: 'Bar on the back plus a deep hinge — one of the highest lower-back demands of any exercise. Very light or not at all.', ru: 'Штанга на спине плюс глубокий наклон — одна из самых высоких нагрузок на поясницу среди всех упражнений. Только очень лёгкий вес или совсем не делать.' },
  'nordic-curl': { sec: ['glutes'], en: 'Anchor the ankles, lower the torso as slowly as possible, catch yourself with the hands. Extremely effective and needs no equipment.', ru: 'Зафиксируйте стопы, опускайте корпус максимально медленно, страхуйте себя руками. Крайне эффективно и не требует оборудования.' },

  /* ---------- Glutes ---------- */
  'hip-thrust': { sec: ['hamstrings', 'core'], en: 'Upper back on a bench, bar across the hips with a pad. Drive the hips up, tuck the ribs down, squeeze at the top — no lower-back arch.', ru: 'Лопатки на скамье, штанга на бёдрах через подушку. Выталкивайте таз вверх, рёбра вниз, сжимайте ягодицы в верхней точке — без прогиба в пояснице.' },
  'hip-thrust-mach': { sec: ['hamstrings'], en: 'Same movement without balancing a bar on your hips. Easier to load progressively and easier on the setup.', ru: 'То же движение, но не нужно балансировать штангу на тазу. Проще прогрессировать в весе и проще устанавливаться.' },
  'kickback': { sec: ['hamstrings'], en: 'Isolation for one glute at a time. Keep the pelvis square — twisting to get more range defeats the point.', ru: 'Изоляция на одну ягодицу за раз. Держите таз ровно — разворот ради большей амплитуды убивает смысл упражнения.' },
  'hip-abduction': { sec: [], en: 'Targets the gluteus medius, which stabilises the pelvis when you walk and squat. Lean the torso slightly forward for more range.', ru: 'Нагружает среднюю ягодичную мышцу, которая стабилизирует таз при ходьбе и приседе. Небольшой наклон корпуса вперёд увеличивает амплитуду.' },

  /* ---------- Calves ---------- */
  'standing-calf': { sec: [], en: 'Straight knee targets the gastrocnemius. Full stretch at the bottom, full contraction at the top, no bouncing.', ru: 'Прямое колено нагружает икроножную мышцу. Полная растяжка внизу, полное сокращение вверху, без пружинистых движений.' },
  'seated-calf': { sec: [], en: 'Bent knee shifts the work to the soleus underneath — the one that adds calf width. Higher reps work well here.', ru: 'Согнутое колено переносит работу на камбаловидную мышцу под икроножной — именно она даёт ширину голени. Здесь хорошо работают высокие повторы.' },
  'leg-press-calf': { sec: [], en: 'Toes on the bottom edge of the platform, knees soft but not locked. Convenient to superset straight after leg press.', ru: 'Носки на нижнем крае платформы, колени мягкие, но не в замке. Удобно делать суперсетом сразу после жима ногами.' },

  /* ---------- Core ---------- */
  'plank': { sec: ['shoulders', 'glutes'], en: 'Forearms under the shoulders, ribs down, glutes squeezed, no sagging hips. If you can hold 90 seconds, add load rather than time.', ru: 'Предплечья под плечами, рёбра опущены, ягодицы напряжены, таз не проваливается. Если держите 90 секунд — добавляйте вес, а не время.' },
  'hanging-leg-raise': { sec: ['forearms'], en: 'Curl the pelvis up towards the ribs rather than just swinging the legs — that\'s what makes the abs work. Bend the knees to make it easier.', ru: 'Подкручивайте таз к рёбрам, а не просто закидывайте ноги — именно это включает пресс. Согнутые колени упрощают вариант.' },
  'cable-crunch': { sec: [], en: 'Kneel facing the stack, rope by the head, flex the spine to bring the elbows to the thighs. Hips stay still — it\'s a crunch, not a hinge.', ru: 'Встаньте на колени лицом к блоку, канат у головы, скручивайте позвоночник, приводя локти к бёдрам. Таз неподвижен — это скручивание, а не наклон.' },
  'woodchopper': { sec: ['shoulders', 'glutes'], en: 'Anti-rotation work for the obliques and deep core. Rotate through the torso with the arms straight, hips facing forward.', ru: 'Работа на косые и глубокие мышцы кора против ротации. Вращение идёт корпусом, руки прямые, таз смотрит вперёд.' },
  'ab-wheel': { sec: ['shoulders', 'back'], en: 'Roll out only as far as you can go without the lower back arching. Start from the knees; this is much harder than it looks.', ru: 'Выкатывайтесь ровно настолько, насколько можете, не прогибая поясницу. Начинайте с колен; упражнение намного сложнее, чем выглядит.' },
  'russian-twist': { sec: [], en: 'Lean back to about 45°, rotate the torso side to side. Slow and controlled beats fast and sloppy for the obliques.', ru: 'Отклонитесь назад примерно на 45°, поворачивайте корпус из стороны в сторону. Для косых медленно и подконтрольно лучше, чем быстро и небрежно.' },
  'dead-bug': { sec: [], en: 'Lower back pressed to the floor throughout while opposite arm and leg extend. Teaches the bracing pattern that protects the spine under load.', ru: 'Поясница всё время прижата к полу, разноимённые рука и нога выпрямляются. Обучает паттерну стабилизации, который защищает позвоночник под нагрузкой.' },
  'side-plank': { sec: ['shoulders', 'glutes'], en: 'Elbow under the shoulder, body in a straight line, hips lifted. Directly trains the lateral core that stabilises the lower back.', ru: 'Локоть под плечом, тело в прямой линии, таз поднят. Прямо тренирует боковой кор, стабилизирующий поясницу.' },

  /* ---------- Forearms ---------- */
  'wrist-curl': { sec: [], en: 'Forearms on the thighs or a bench, wrists hanging over the edge. High reps — the forearms respond to volume.', ru: 'Предплечья на бёдрах или скамье, кисти свисают за край. Высокие повторы — предплечья отзываются на объём.' },
  'farmers-carry': { sec: ['core', 'back', 'glutes'], en: 'Heavy dumbbells, walk tall with the ribs down and shoulders back. Builds grip, core stability and general work capacity at once.', ru: 'Тяжёлые гантели, идите с прямой спиной, рёбра опущены, плечи назад. Развивает хват, стабильность корпуса и общую выносливость сразу.' },

  /* ---------- Cardio ---------- */
  'treadmill': { sec: ['quads', 'calves'], en: 'Low-intensity walking, conversational pace. Keep it to ~15–20 min so it doesn\'t eat into the calorie surplus you need to gain.', ru: 'Ходьба низкой интенсивности, темп, при котором можно разговаривать. Держите в пределах 15–20 минут, чтобы не съедать профицит калорий, нужный для набора.' },
  'bike': { sec: ['quads', 'hamstrings'], en: 'Easy cycling is the least intrusive cardio for a gaining phase — no impact, low calorie cost, no interference with leg training.', ru: 'Спокойный велотренажёр — наименее конфликтное кардио в фазе набора: без ударной нагрузки, малый расход калорий, не мешает тренировке ног.' },
  'rowing': { sec: ['back', 'quads', 'biceps'], en: 'Full-body and fairly demanding. Drive with the legs first, then lean back, then pull — arms last, not first.', ru: 'Задействует всё тело и довольно требователен. Сначала толчок ногами, затем отклонение корпуса, затем тяга руками — руки в последнюю очередь.' },
  'elliptical': { sec: ['quads', 'glutes'], en: 'Zero impact, easy on the joints and the lower back. A good default when the knees or spine don\'t want running.', ru: 'Нулевая ударная нагрузка, щадит суставы и поясницу. Хороший вариант по умолчанию, когда колени или спина против бега.' },
  'stair-climber': { sec: ['glutes', 'quads', 'calves'], en: 'Higher calorie burn than walking — use sparingly during a gaining phase. Stand tall, don\'t lean on the handles.', ru: 'Сжигает больше калорий, чем ходьба, — в фазе набора используйте умеренно. Стойте прямо, не наваливайтесь на поручни.' },
  /* ---------- added in v3.4: wider library ---------- */
  'decline-bench': { sec: ['triceps', 'shoulders'], en: 'Feet hooked under the pads, shoulder blades pulled back. Use a moderate load, lower the bar to the lower chest and press straight up with the elbows tucked, not flared.', ru: 'Ноги зафиксированы под валиками, лопатки сведены. Берите умеренный вес, опускайте гриф к низу груди и выжимайте вверх, держа локти ближе к корпусу, а не разводя их в стороны.' },
  'db-fly': { sec: ['shoulders'], en: 'Lie flat, dumbbells over the chest, elbows slightly bent and fixed. Open the arms in a wide arc to a comfortable stretch and return the same way, without turning it into a press.', ru: 'Лягте на скамью, гантели над грудью, локти чуть согнуты и зафиксированы. Разводите руки по широкой дуге до комфортного растяжения и возвращайте по той же дуге, не превращая движение в жим.' },
  'incline-db-fly': { sec: ['shoulders'], en: 'Keep the bench at a low incline, since a steeper one shifts the work to the front delts. With the elbows slightly bent, arc the dumbbells out to a stretch and back together over the upper chest.', ru: 'Спинку скамьи поднимайте невысоко, иначе работу перехватят передние дельты. Локти чуть согнуты, разводите гантели до растяжения и сводите их над верхом груди.' },
  'smith-bench': { sec: ['triceps', 'shoulders'], en: 'Slide the bench so the bar meets mid-chest, and set the safety stops. Keep the load moderate and the elbows tucked, not flared, because the fixed bar path will not adjust to your shoulders.', ru: 'Поставьте скамью так, чтобы гриф опускался на середину груди, и выставьте страховочные упоры. Берите умеренный вес и не разводите локти в стороны, ведь траектория в Смите фиксированная и под ваши плечи не подстроится.' },
  'smith-incline': { sec: ['triceps', 'shoulders'], en: 'Set a low incline and slide the bench until the bar lands on the upper chest. Use a moderate load and keep the elbows slightly tucked instead of flaring them out to the sides.', ru: 'Поставьте скамью под небольшим наклоном и сдвиньте её так, чтобы гриф опускался на верх груди. Вес умеренный, локти чуть прижаты к корпусу, в стороны их не разводите.' },
  'incline-machine-press': { sec: ['triceps', 'shoulders'], en: 'Set the seat so the handles start level with the upper chest. Press with the shoulder blades kept against the pad, and do not let the shoulders roll forward at the top.', ru: 'Настройте сиденье так, чтобы рукояти были на уровне верха груди. Жмите, не отрывая лопатки от спинки, и не выводите плечи вперёд в верхней точке.' },
  'landmine-press': { sec: ['shoulders', 'triceps', 'core'], en: 'Stand in a split stance holding the end of the bar at the chest, ribs down. Press up and forward without leaning back, and if you press with one hand, train both sides.', ru: 'Встаньте в разножку, конец грифа у груди, рёбра опущены. Выжимайте вверх и вперёд, не отклоняясь назад, а если жмёте одной рукой, проработайте обе стороны.' },
  'cable-crossover-high': { sec: ['shoulders'], en: 'Pulleys set high, one foot forward, a slight lean and soft elbows. Sweep the handles down and together in front of the hips, keeping the elbow angle fixed so it never turns into a pushdown.', ru: 'Блоки вверху, шаг одной ногой вперёд, лёгкий наклон корпуса, локти слегка согнуты. Сводите рукояти вниз перед бёдрами, не меняя угол в локтях, иначе сведение превратится в разгибание рук на блоке.' },
  'low-cable-fly': { sec: ['shoulders'], en: 'Pulleys at the bottom, palms facing up, elbows softly bent. Sweep the handles up and together at upper chest height, shoulders down, so the chest does the work, not the front delts.', ru: 'Блоки внизу, ладони смотрят вверх, локти слегка согнуты. Сводите рукояти снизу вверх до уровня верха груди, плечи опущены, чтобы работала грудь, а не передние дельты.' },
  'weighted-push-up': { sec: ['triceps', 'shoulders', 'core'], en: 'Plate high on the upper back or a weight vest, body in one straight line. Lower the chest to the floor with the elbows angled back, and do not let the hips sag under the extra load.', ru: 'Блин на верхней части спины или жилет-утяжелитель, тело в одну линию. Опускайтесь грудью к полу, уводя локти назад вдоль корпуса, и не давайте тазу провисать под дополнительным весом.' },
  'incline-push-up': { sec: ['triceps', 'shoulders'], en: 'Hands on a bench slightly wider than the shoulders, body straight from head to heels. Touch the chest to the edge and push away, then move to a lower surface as it gets easy.', ru: 'Руки на скамье чуть шире плеч, тело прямое от головы до пяток. Касайтесь грудью края скамьи и отталкивайтесь, а когда станет легко, переходите на опору пониже.' },
  'chin-up': { sec: ['biceps', 'forearms'], en: 'Palms facing you, hands about shoulder-width, start from a full hang. Pull the chest towards the bar until the chin clears it, and lower all the way down instead of cutting reps short.', ru: 'Обратный хват примерно на ширине плеч, старт из полного виса. Тянитесь грудью к перекладине, пока подбородок не окажется выше неё, и опускайтесь до конца, не срезая амплитуду.' },
  'neutral-pulldown': { sec: ['biceps'], en: 'Close neutral-grip handle, thighs locked under the pads. Pull to the upper chest by driving the elbows down to your sides, chest up, without swinging the torso back to move the weight.', ru: 'Узкая параллельная рукоять, бёдра зафиксированы под валиками. Тяните к верху груди, направляя локти вниз к бокам, грудь раскрыта, и не раскачивайте корпус назад, чтобы сдвинуть вес.' },
  'sa-lat-pulldown': { sec: ['biceps'], en: 'Single handle on a high pulley, arm fully stretched overhead at the start. Drive the elbow down towards the hip without twisting the torso, then repeat on the other side.', ru: 'Одиночная рукоять на верхнем блоке, в начале рука полностью вытянута вверх. Тяните локоть вниз к бедру, не скручивая корпус, затем повторите другой рукой.' },
  'reverse-pulldown': { sec: ['biceps'], en: 'Underhand grip about shoulder-width, thighs under the pads. Pull the bar to the upper chest by driving the elbows down past the ribs, rather than curling it down with the biceps.', ru: 'Обратный хват примерно на ширине плеч, бёдра под валиками. Тяните рукоять к верху груди, опуская локти вниз вдоль корпуса, а не сгибая руки за счёт бицепса.' },
  'inverted-row': { sec: ['biceps', 'shoulders'], en: 'Hang under a bar set at about waist height, body straight from heels to shoulders. Pull the chest to the bar and squeeze the shoulder blades, without letting the hips sag.', ru: 'Повисните под грифом, закреплённым примерно на уровне пояса, тело прямое от пяток до плеч. Тянитесь грудью к грифу, сводя лопатки, и не давайте тазу провисать.' },
  'pendlay-row': { sec: ['biceps', 'shoulders'], en: 'Hinge until the torso is nearly parallel to the floor, bar resting on the floor. Row it to the lower chest and return it to the floor each rep, with a moderate load and a neutral spine.', ru: 'Наклон корпуса почти до параллели с полом, штанга стоит внизу. Тяните её к низу груди и в каждом повторе опускайте обратно на пол, вес умеренный, спина нейтральная.' },
  'seal-row': { sec: ['biceps', 'shoulders'], en: 'Lie face down on a high bench, arms hanging straight. Row the bar up until it touches the bench and keep the chest on the pad, so the upper back does the work instead of momentum.', ru: 'Лягте животом на высокую скамью, руки свободно свисают. Тяните штангу, пока она не коснётся скамьи, и не отрывайте грудь от опоры, чтобы работала спина, а не инерция.' },
  'machine-row': { sec: ['biceps', 'shoulders'], en: 'Set the chest pad so you reach the handles with the arms fully extended. Drive the elbows back and squeeze the shoulder blades together, chest on the pad, without shrugging towards the ears.', ru: 'Настройте упор так, чтобы доставать до рукоятей прямыми руками. Отводите локти назад и сводите лопатки, грудь прижата к упору, плечи к ушам не поднимайте.' },
  'wide-cable-row': { sec: ['shoulders', 'biceps'], en: 'Wide bar on the low pulley, sit tall, knees soft. Row to the lower chest with the elbows out wide to hit the upper back and rear delts, and keep the torso still instead of rocking.', ru: 'Широкая рукоять на нижнем блоке, сидите ровно, колени слегка согнуты. Тяните к низу груди, разводя локти в стороны, чтобы нагрузить верх спины и задние дельты, и не раскачивайте корпус.' },
  'bb-shrug': { sec: ['forearms'], en: 'Bar against the thighs, grip about shoulder-width, arms straight. Shrug straight up towards the ears and lower under control, without dipping the knees to heave the weight up.', ru: 'Штанга у бёдер, хват примерно на ширине плеч, руки прямые. Поднимайте плечи строго вверх к ушам и подконтрольно опускайте, не помогая себе ногами.' },
  'trap-bar-deadlift': { sec: ['quads', 'glutes', 'hamstrings'], en: 'Stand in the middle of the bar, grip the handles, hips down and chest up. Brace and push the floor away, using a moderate load and keeping the spine neutral from the floor to lockout.', ru: 'Встаньте в центр грифа, возьмитесь за рукояти, таз опущен, грудь раскрыта. Напрягите корпус и отталкивайтесь ногами от пола, вес умеренный, спина нейтральная от старта до полного выпрямления.' },
  'sumo-deadlift': { sec: ['glutes', 'quads', 'hamstrings'], en: 'Wide stance, toes turned out, hands inside the knees, bar close to the shins. Push the knees out and drive the floor away, keeping the load moderate and the spine neutral, never rounded.', ru: 'Широкая постановка ног, носки развёрнуты наружу, руки внутри коленей, гриф у самых голеней. Разводите колени в стороны и отталкивайтесь от пола, вес умеренный, спина нейтральная, без округления.' },
  'back-extension': { sec: ['glutes', 'hamstrings'], en: 'Set the pad just below the hip bones so the bend happens at the hips. Lower with a neutral back and rise until the body forms a straight line, without arching past it at the top.', ru: 'Выставьте упор чуть ниже тазовых костей, чтобы наклон шёл в тазобедренных суставах. Опускайтесь с нейтральной спиной и поднимайтесь до прямой линии тела, не прогибаясь в пояснице вверху.' },
  'machine-back-ext': { sec: ['glutes', 'hamstrings'], en: 'Sit with the feet braced and the pad across the upper back. Push back smoothly until upright and return under control, without yanking the weight or leaning far past vertical.', ru: 'Сядьте, упритесь ногами, валик на верхней части спины. Плавно разгибайтесь до вертикали и подконтрольно возвращайтесь, без рывков и без сильного отклонения назад.' },
  'db-pullover': { sec: ['chest', 'triceps'], en: 'Lie on a bench holding one dumbbell over the chest with both hands, elbows slightly bent. Arc it back behind the head to a stretch and pull it back up, without bending the elbows further.', ru: 'Лягте на скамью и держите одну гантель обеими руками над грудью, локти чуть согнуты. Опускайте её по дуге за голову до растяжения и возвращайте обратно, не сгибая локти сильнее.' },
  'arnold-press': { sec: ['triceps'], en: 'Sit with back support, dumbbells at shoulder height, palms facing you. Rotate the palms forward as you press overhead and reverse on the way down, keeping the lower back against the pad.', ru: 'Сидя с опорой на спинку, гантели на уровне плеч, ладони к себе. Разворачивайте ладони вперёд по ходу жима и обратно при опускании, поясница прижата к спинке.' },
  'reverse-pec-deck': { sec: ['back'], en: 'Chest against the pad, handles at shoulder height, elbows slightly bent. Sweep the arms out and back to line up with the body, shoulders down so the rear delts work, not the traps.', ru: 'Сядьте лицом к спинке, грудь прижата, рукояти на уровне плеч, локти слегка согнуты. Разводите руки в стороны и назад до линии корпуса, плечи опущены, чтобы работали задние дельты, а не трапеции.' },
  'machine-lateral': { sec: [], en: 'Set the seat so the shoulders line up with the pivot, pads resting on the outer arms. Raise with the elbows to shoulder height and lower slowly, without shrugging to help the weight up.', ru: 'Настройте сиденье так, чтобы плечи были на одной линии с осью тренажёра, валики прилегают к рукам снаружи. Поднимайте локтями до уровня плеч и медленно опускайте, не помогая себе трапециями.' },
  'cable-ext-rotation': { sec: ['back'], en: 'Pulley at elbow height, stand side-on and hold the handle in the far hand. Rotate the forearm outward without the elbow leaving your side, keep the weight light, and repeat with the other arm.', ru: 'Блок на уровне локтя, встаньте к нему боком и возьмите рукоять дальней рукой. Разворачивайте предплечье наружу, не отрывая локоть от корпуса, вес лёгкий, затем повторите другой рукой.' },
  'band-pull-apart': { sec: ['back'], en: 'Band at chest height, arms straight, hands about shoulder-width. Pull it apart to the chest by squeezing the shoulder blades, and control the return instead of letting it snap back.', ru: 'Резинка на уровне груди, руки прямые, хват примерно на ширине плеч. Растягивайте её до касания груди, сводя лопатки, и возвращайте подконтрольно, не давая резинке резко стянуть руки обратно.' },
  'plate-front-raise': { sec: ['chest'], en: 'Grip the plate at the sides, arms almost straight, knees soft. Raise it to shoulder height and lower slowly, keeping the torso still instead of leaning back to swing it up.', ru: 'Возьмите блин за края, руки почти прямые, колени слегка согнуты. Поднимайте до уровня плеч и медленно опускайте, корпус неподвижен, без отклонения назад и раскачки.' },
  'y-raise': { sec: ['back'], en: 'Lie chest-down on an incline bench with light dumbbells, thumbs pointing up. Raise the arms up and out into a Y, keeping the shoulders down and away from the ears.', ru: 'Лягте грудью на наклонную скамью, лёгкие гантели, большие пальцы смотрят вверх. Поднимайте руки вверх и в стороны буквой Y, плечи опущены и не тянутся к ушам.' },
  'cable-rear-delt': { sec: ['back'], en: 'Pulleys at shoulder height, cables crossed so each hand holds the opposite side. Sweep the arms out wide with soft elbows until they line up with the body, without bending them into a row.', ru: 'Блоки на уровне плеч, тросы перекрещены, каждая рука держит трос с противоположной стороны. Разводите руки в стороны до линии корпуса, локти чуть согнуты, не превращайте движение в тягу.' },
  'ez-curl': { sec: ['forearms'], en: 'Hold the bar on its angled bends, elbows fixed at your sides. Curl without rocking the torso and lower to full extension instead of cutting the rep short at the bottom.', ru: 'Хват за изгибы грифа, локти прижаты к бокам. Поднимайте гриф без раскачки корпуса и опускайте до полного выпрямления рук, не укорачивая амплитуду внизу.' },
  'concentration-curl': { sec: ['forearms'], en: 'Sit on a bench with the elbow braced against the inner thigh. Curl towards the shoulder without the torso helping, lower to full extension and repeat with the other arm.', ru: 'Сядьте на скамью, локоть упирается во внутреннюю часть бедра. Поднимайте гантель к плечу, не помогая корпусом, опускайте до полного выпрямления руки и повторите другой рукой.' },
  'spider-curl': { sec: ['forearms'], en: 'Lie chest down on an incline bench, arms hanging straight to the floor. Curl without letting the elbows drift forward and squeeze hard at the top, where this curl is hardest.', ru: 'Лягте грудью на наклонную скамью, руки свисают вертикально вниз. Сгибайте руки, не выводя локти вперёд, и сильно напрягайте бицепс в верхней точке, где нагрузка максимальна.' },
  'reverse-curl': { sec: ['forearms'], en: 'Overhand grip at shoulder width, elbows at your sides, wrists kept straight. The palms-down grip shifts work to the forearms, so expect to use less weight than on a regular curl.', ru: 'Хват сверху на ширине плеч, локти прижаты к корпусу, запястья прямые. Такой хват переносит часть нагрузки на предплечья, поэтому вес будет меньше, чем в обычном подъёме на бицепс.' },
  'rope-hammer-curl': { sec: ['forearms'], en: 'Rope on the low pulley, palms facing each other, elbows at your sides. Curl the ends to the shoulders without leaning back, and resist the rope on the way down instead of letting it drop.', ru: 'Канат на нижнем блоке, ладони смотрят друг на друга, локти прижаты к корпусу. Тяните концы каната к плечам, не отклоняясь назад, и опускайте подконтрольно, не бросая вес.' },
  'machine-curl': { sec: ['forearms'], en: 'Set the seat so your elbows line up with the machine\'s pivot, upper arms flat on the pad. Curl through the full range without shrugging the shoulders or lifting off the seat.', ru: 'Настройте сиденье так, чтобы локти были на одной оси с шарниром тренажёра, а руки плотно лежали на пюпитре. Сгибайте руки в полной амплитуде, не поднимая плечи и не отрывая таз от сиденья.' },
  'bayesian-curl': { sec: ['forearms'], en: 'Face away from a low pulley and step forward so the arm trails behind your body. Keep the elbow back as you curl to hold the biceps stretch, then repeat with the other arm.', ru: 'Встаньте спиной к нижнему блоку и шагните вперёд, рабочая рука остаётся позади корпуса. Сгибайте руку, не выводя локоть вперёд, чтобы сохранить растяжение бицепса, затем повторите другой рукой.' },
  'oh-cable-ext': { sec: [], en: 'Face away from the pulley in a split stance with the rope behind your head. Extend until the arms are straight while the elbows stay in place, pointing forward and not flaring out.', ru: 'Встаньте спиной к блоку в разножке, канат за головой. Разгибайте руки до конца, локти остаются на месте, смотрят вперёд и не разъезжаются в стороны.' },
  'sa-pushdown': { sec: [], en: 'Single handle on a high pulley, elbow tucked to your side. Push down to full extension moving only the forearm, without the shoulder rolling forward, then switch arms.', ru: 'Одиночная рукоять на верхнем блоке, локоть прижат к боку. Разгибайте руку до конца, двигается только предплечье, плечо не заваливается вперёд, затем повторите другой рукой.' },
  'db-kickback': { sec: ['shoulders'], en: 'Hand and knee on a bench, torso flat, upper arm tight to your side and parallel to the floor. Straighten the elbow without the upper arm dropping or swinging, then do the other side.', ru: 'Рука и колено на скамье, спина ровная, локоть прижат к корпусу на уровне спины. Разгибайте руку назад до конца, локоть не опускается и не болтается, затем повторите другой рукой.' },
  'dip-machine': { sec: ['chest', 'shoulders'], en: 'Torso upright and elbows travelling straight back, not out to the sides. Lower only until the upper arms are level with the floor and keep the shoulders down, away from the ears.', ru: 'Корпус вертикально, локти уходят назад, а не в стороны. Опускайтесь до параллели, не ниже, и держите плечи опущенными, подальше от ушей.' },
  'diamond-push-up': { sec: ['chest', 'shoulders'], en: 'Hands together under the chest, thumbs and index fingers forming a diamond, body in a straight line. Lower the chest to the hands, elbows going back along the body, hips never sagging.', ru: 'Ладони вместе под грудью, большие и указательные пальцы образуют ромб, тело в одну линию. Опускайтесь грудью к кистям, локти уходят назад вдоль корпуса, таз не проваливается.' },
  'jm-press': { sec: ['chest'], en: 'Shoulder-width grip, elbows tucked and pointing towards your feet. Use a moderate weight and lower the bar towards the upper chest by folding the elbows, never letting them flare out.', ru: 'Хват на ширине плеч, локти прижаты и смотрят в сторону ног. Работайте с умеренным весом и опускайте гриф к верху груди, сгибая руки в локтях и не разводя их в стороны.' },
  'db-lying-ext': { sec: [], en: 'Lie on a flat bench, dumbbells above the shoulders with palms facing each other. Bend only at the elbows to lower the dumbbells beside your head, keeping the elbows from drifting out.', ru: 'Лягте на горизонтальную скамью, гантели над плечами, ладони смотрят друг на друга. Опускайте гантели по бокам от головы, двигаются только предплечья, локти не разъезжаются в стороны.' },
  'machine-triceps-ext': { sec: [], en: 'Adjust the seat so the elbows sit in line with the pivot and the upper arms rest flat on the pad. Extend fully and return under control, without leaning the torso into the handles.', ru: 'Настройте сиденье так, чтобы локти были на оси вращения, а руки плотно лежали на подушке. Разгибайте до конца и возвращайте подконтрольно, не наваливаясь корпусом на рукояти.' },
  'reverse-wrist-curl': { sec: [], en: 'Forearms on your thighs or a bench, palms down, wrists just past the edge. Raise the backs of the hands using only the wrists, going much lighter than on a regular wrist curl.', ru: 'Предплечья на бёдрах или на скамье, ладони вниз, кисти свисают за край. Поднимайте кисти только движением в запястьях и берите вес заметно легче, чем в обычных сгибаниях запястий.' },
  'btb-wrist-curl': { sec: [], en: 'Stand holding the bar behind your back, arms straight and palms facing back. Let it roll down to the fingertips, then curl it up with the wrists alone, never bending the elbows to help.', ru: 'Встаньте, держа штангу за спиной на прямых руках, ладони смотрят назад. Дайте грифу скатиться к кончикам пальцев, затем поднимите его одними кистями, не сгибая руки в локтях.' },
  'wrist-roller': { sec: ['shoulders'], en: 'Arms straight out in front at shoulder height, overhand grip on the roller. Wind the weight up with small wrist turns, then unwind it under control instead of letting it spin down.', ru: 'Руки прямые, вытянуты перед собой на уровне плеч, хват сверху. Наматывайте верёвку короткими поворотами кистей, затем разматывайте её подконтрольно, не давая грузу падать.' },
  'dead-hang': { sec: ['back', 'shoulders'], en: 'Overhand grip at shoulder width, arms straight, legs relaxed and body still. Keep light tension in the shoulders so they don\'t creep up to the ears, and breathe steadily throughout.', ru: 'Хват сверху на ширине плеч, руки прямые, ноги расслаблены, тело неподвижно. Держите плечи в лёгком тонусе, чтобы они не поднимались к ушам, и дышите ровно всё время виса.' },
  'plate-pinch': { sec: [], en: 'Pinch a pair of plates in each hand, smooth sides out, thumb on one face and fingers on the other. Stand tall with the shoulders down and breathe steadily for the whole hold.', ru: 'В каждой руке по паре блинов гладкой стороной наружу, большой палец с одной стороны, остальные с другой. Стойте прямо, плечи опущены, дышите ровно всё время удержания.' },
  'step-up': { sec: ['glutes', 'hamstrings'], en: 'Dumbbells at your sides, place the whole foot on a sturdy box or bench. Stand up by driving through that leg rather than pushing off the back foot, then repeat on the other leg.', ru: 'Гантели по бокам, поставьте всю стопу на устойчивую тумбу или скамью. Вставайте усилием этой ноги, не отталкиваясь задней, затем повторите на другую ногу.' },
  'reverse-lunge': { sec: ['glutes', 'hamstrings'], en: 'Dumbbells at your sides, step back and lower the rear knee towards the floor with the torso upright. Drive through the front foot to return and work both legs evenly.', ru: 'Гантели по бокам, шагните назад и опустите заднее колено к полу, корпус вертикально. Вернитесь толчком передней ноги и прорабатывайте обе ноги одинаково.' },
  'smith-squat': { sec: ['glutes', 'hamstrings'], en: 'Bar across the upper back, feet slightly in front of the bar. Squat with a moderate load and a neutral spine, stopping before the lower back starts to round.', ru: 'Гриф на верхней части спины, стопы чуть впереди грифа. Приседайте с умеренным весом, спина нейтральная, останавливайтесь раньше, чем поясница начнёт круглиться.' },
  'belt-squat': { sec: ['glutes', 'hamstrings'], en: 'Belt snug around the hips, chest up, sit straight down between the feet and drive back up. The weight hangs from the hips, so the legs get a heavy squat with no bar on the back.', ru: 'Пояс плотно застёгнут на бёдрах, грудь раскрыта, опускайтесь вертикально вниз между стопами и вставайте. Вес висит на тазу, поэтому ноги получают тяжёлый присед без штанги на спине.' },
  'pendulum-squat': { sec: ['glutes'], en: 'Back and shoulders flat against the pads, feet in the middle of the platform. Sink deep under control, letting the knees travel forward, and keep the heels down as you drive up.', ru: 'Спина и плечи плотно прижаты к упорам, стопы по центру платформы. Опускайтесь глубоко и подконтрольно, позволяя коленям уходить вперёд, и не отрывайте пятки на подъёме.' },
  'sissy-squat': { sec: ['core'], en: 'Hold a support with one hand and rise onto the balls of your feet. Push the knees forward while leaning back, keeping a straight line from knees to shoulders instead of sitting back at the hips.', ru: 'Держитесь одной рукой за опору и встаньте на носки. Выводите колени вперёд, отклоняя корпус назад, тело от коленей до плеч в одну линию, таз назад не отводите.' },
  'sl-leg-press': { sec: ['glutes', 'hamstrings'], en: 'One foot centred on the platform, hips and lower back flat against the pad. Lower until just before the hips start to lift, keeping the knee in line with the toes, then switch legs.', ru: 'Одна стопа по центру платформы, таз и поясница прижаты к спинке. Опускайте платформу, пока таз остаётся прижатым, колено смотрит по линии носка, затем смените ногу.' },
  'split-squat': { sec: ['glutes', 'hamstrings'], en: 'Dumbbells at your sides, feet in a long split stance with the back heel raised. Drop straight down until the back knee nearly touches the floor, feet staying put, then switch sides.', ru: 'Гантели по бокам, ноги в длинной разножке, пятка задней ноги поднята. Опускайтесь строго вниз, пока заднее колено почти не коснётся пола, стопы остаются на месте, затем смените ногу.' },
  'hip-adduction': { sec: ['glutes'], en: 'Sit back in the seat, pads on the inner thighs, and start from a comfortable stretch. Squeeze the legs together and open them under control, never letting the weight yank them apart.', ru: 'Сядьте глубоко в тренажёр, упоры на внутренней стороне бёдер, начинайте с комфортной растяжки. Сводите ноги вместе и возвращайте их подконтрольно, не позволяя весу рывком разводить их в стороны.' },
  'sl-rdl': { sec: ['glutes', 'core'], en: 'Stand on one leg with a soft knee, dumbbell in the opposite hand. Hinge at the hips as the free leg reaches back in line with the torso, hips square to the floor, then switch legs.', ru: 'Встаньте на одну ногу с чуть согнутым коленом, гантель в противоположной руке. Наклоняйтесь в тазобедренном суставе, свободная нога уходит назад в линию с корпусом, таз не разворачивается, затем смените ногу.' },
  'cable-pull-through': { sec: ['glutes', 'back'], en: 'Face away from a low pulley, rope between your legs. Hinge the hips back with soft knees, then drive them forward to stand tall, arms acting only as hooks and never pulling.', ru: 'Встаньте спиной к нижнему блоку, канат между ног. Отводите таз назад с чуть согнутыми коленями, затем толкайте его вперёд и выпрямляйтесь, руки только держат канат и не тянут.' },
  'ghr': { sec: ['glutes', 'calves'], en: 'Feet against the plate, knees just behind the pad, body straight from knees to head. Pull yourself up with the hamstrings and never break at the hips to make the rep easier.', ru: 'Стопы упираются в платформу, колени чуть позади подушки, тело прямое от коленей до головы. Поднимайтесь усилием бицепса бедра и не ломайтесь в тазу ради облегчения подъёма.' },
  'sldl': { sec: ['glutes', 'back'], en: 'Feet hip-width, knees almost straight but not locked, bar close to the legs. Use a moderate load, hinge with a neutral spine and stop as soon as the lower back wants to round.', ru: 'Стопы на ширине таза, колени почти прямые, но не в замке, гриф близко к ногам. Работайте с умеренным весом, наклоняйтесь с нейтральной спиной и останавливайтесь, как только поясница начинает круглиться.' },
  'kb-swing': { sec: ['glutes', 'core', 'back'], en: 'Hike the bell back between your legs with a flat back, then snap the hips forward so it floats up to chest height. The power comes from the hips, not from lifting with the arms.', ru: 'Заведите гирю назад между ног с ровной спиной, затем резко выведите таз вперёд, чтобы она взлетела до уровня груди. Мах делается тазом, руки гирю не поднимают, а только направляют.' },
  'standing-leg-curl': { sec: ['calves'], en: 'Front of the thigh against the pad, roller just above the heel, hands on the handles. Curl the heel towards the glutes without the hips swinging or the lower back arching, then switch legs.', ru: 'Бедро упирается в подушку, валик чуть выше пятки, руки на рукоятях. Сгибайте ногу, подтягивая пятку к ягодице, без раскачки таза и прогиба в пояснице, затем смените ногу.' },
  'ball-leg-curl': { sec: ['glutes', 'core'], en: 'Lie on your back, heels on the ball, hips lifted into a bridge. Pull the ball in with your heels and roll it back out, keeping the hips high instead of letting them sag.', ru: 'Лягте на спину, пятки на фитболе, таз поднят в мостик. Подкатывайте мяч пятками к себе и откатывайте обратно, таз всё время держите высоко и не давайте ему провисать.' },
  'glute-bridge': { sec: ['hamstrings'], en: 'Lie on your back, feet flat near the hips. Drive through the heels until the body forms a straight line, squeeze the glutes, ribs down, no lower-back arch.', ru: 'Лёжа на спине, стопы стоят на полу ближе к тазу. Толкайтесь пятками до прямой линии корпуса, сжимайте ягодицы, рёбра вниз, без прогиба в пояснице.' },
  'sl-hip-thrust': { sec: ['hamstrings'], en: 'Upper back on a bench, one foot planted, the other leg lifted. Drive the hips up through the heel, keep the pelvis level and work both legs equally.', ru: 'Лопатки на скамье, одна нога в упоре, вторая поднята. Выталкивайте таз вверх через пятку, не давая ему заваливаться набок, и выполняйте поровну на обе ноги.' },
  'smith-hip-thrust': { sec: ['hamstrings'], en: 'Upper back on a bench, Smith bar across the hips with a pad. Drive up and squeeze the glutes at the top: the fixed path lets you focus on the hips, not on balance.', ru: 'Лопатки на скамье, гриф Смита лежит на бёдрах через подушку. Выталкивайте таз вверх и сжимайте ягодицы наверху: фиксированная траектория позволяет думать о тазе, а не о балансе.' },
  'reverse-hyper': { sec: ['hamstrings', 'back'], en: 'Lie face down, hips at the edge of the pad, hands on the handles. Lift the legs with the glutes, not momentum, and stop at hip level without arching the lower back.', ru: 'Лягте животом на подушку, таз у края, руки на рукоятях. Поднимайте ноги силой ягодиц, а не махом, и останавливайтесь на уровне таза, не прогибая поясницу.' },
  'band-abduction': { sec: [], en: 'Band just above the knees, feet hip-width apart. Push the knees out against the band, pause and control the way back, keeping the torso still so the side glutes do the work.', ru: 'Резинка чуть выше колен, стопы на ширине таза. Разводите колени против сопротивления, делайте паузу и подконтрольно возвращайте, корпус неподвижен, чтобы работали средние ягодичные.' },
  'cable-abduction': { sec: [], en: 'Cuff on the ankle farther from the stack, stand side-on and hold the frame. Lift the leg out to the side without leaning the torso away, and do both legs.', ru: 'Манжета на дальней от блока ноге, встаньте боком и держитесь за стойку. Отводите ногу в сторону, не заваливая корпус в противоположную сторону, и выполните на обе ноги.' },
  'donkey-calf': { sec: [], en: 'Hips bent and torso leaning forward, balls of the feet on the platform. The hinge deepens the calf stretch, so lower the heels all the way and rise high onto the toes.', ru: 'Корпус в наклоне, таз отведён назад, носки на платформе. Наклон сильнее растягивает икроножные, поэтому опускайте пятки до конца и поднимайтесь высоко на носки.' },
  'sl-calf-raise': { sec: [], en: 'One foot on a step, dumbbell in the same-side hand, other hand on a support. Full stretch at the bottom and full rise at the top with no bouncing, then do the other leg.', ru: 'Одна нога на ступеньке, гантель в руке с той же стороны, другой рукой держитесь за опору. Полная растяжка внизу и полный подъём вверху без пружинки, затем повторите на другую ногу.' },
  'smith-calf': { sec: [], en: 'Bar across the upper back, balls of the feet on a plate or step. The rails take care of balance, so lower the heels slowly and pause high on the toes.', ru: 'Гриф на верхней части спины, носки на блине или степе. Баланс держат направляющие, так что медленно опускайте пятки и задерживайтесь наверху на носках.' },
  'tibialis-raise': { sec: [], en: 'Back against a wall, heels about a step away from it. Lift the toes as high as you can and lower slowly to strengthen the front of the shin, which balances the calves.', ru: 'Спиной к стене, пятки примерно в шаге от неё. Поднимайте носки как можно выше и медленно опускайте: так укрепляется передняя мышца голени, которая уравновешивает икры.' },
  'lying-leg-raise': { sec: ['quads'], en: 'Lie on a bench and hold its edge behind your head. Brace the abs and lower the legs only as far as the lower back stays pressed down, then lift with control.', ru: 'Лягте на скамью и держитесь за её край за головой. Напрягите пресс и опускайте ноги лишь до тех пор, пока поясница прижата, затем подконтрольно поднимайте.' },
  'crunch': { sec: [], en: 'Lie on your back, knees bent, hands lightly by the head without pulling on the neck. Brace the abs and curl the ribs towards the pelvis, lower back staying on the floor.', ru: 'Лёжа на спине, колени согнуты, руки у головы, шею не тяните. Напрягите пресс и подкручивайте рёбра к тазу, поясница остаётся на полу.' },
  'machine-crunch': { sec: [], en: 'Adjust the seat so the pads sit on the chest or shoulders. Brace and curl the ribs down with the abs, not the arms, and return slowly without the lower back taking over.', ru: 'Настройте сиденье так, чтобы валики лежали на груди или плечах. Скручивайтесь напряжённым прессом, а не руками, и медленно возвращайтесь, не перекладывая работу на поясницу.' },
  'rotary-torso': { sec: [], en: 'Sit tall, abs braced, lower back neutral rather than arched. Turn slowly with the obliques and control the return without jerking, working both directions.', ru: 'Сядьте ровно, пресс напряжён, поясница нейтральная, без прогиба. Поворачивайтесь медленно за счёт косых и подконтрольно возвращайтесь без рывков, работая в обе стороны.' },
  'captains-chair': { sec: ['quads'], en: 'Forearms on the pads, back against the backrest. Brace the abs and lift the knees by curling the pelvis up, lower back on the pad, then lower without swinging.', ru: 'Предплечья на упорах, спина прижата к спинке. Напрягите пресс, поднимайте колени, подкручивая таз вверх и не отрывая поясницу от спинки, опускайте без раскачки.' },
  'decline-sit-up': { sec: ['quads'], en: 'Feet hooked under the rollers, arms across the chest. Brace the abs, roll up one vertebra at a time, lower with control and shorten the range if the lower back strains.', ru: 'Зацепитесь ногами за валики, руки скрещены на груди. Напрягите пресс, поднимайтесь, скругляя спину позвонок за позвонком, опускайтесь подконтрольно, а если тянет поясницу, уменьшите амплитуду.' },
  'decline-crunch': { sec: [], en: 'Feet hooked, lower back resting on the bench. Brace and lift only the shoulder blades by curling the ribs to the pelvis, which keeps it gentler than a full sit-up.', ru: 'Ноги зафиксированы, поясница лежит на скамье. Напрягите пресс и отрывайте только лопатки, подкручивая рёбра к тазу: поясница остаётся на скамье, поэтому это мягче полного подъёма корпуса.' },
  'bicycle-crunch': { sec: [], en: 'Lower back pressed to the floor, abs braced. Bring one elbow towards the opposite knee as the other leg extends, switching sides and rotating the ribs rather than yanking the neck.', ru: 'Поясница прижата к полу, пресс напряжён. Тянитесь локтем к противоположному колену, выпрямляя другую ногу, меняйте стороны и поворачивайте корпус, а не дёргайте шею.' },
  'reverse-crunch': { sec: [], en: 'Lie on your back, knees bent over the hips. Brace and curl the pelvis up towards the ribs with the abs, not a leg swing, then lower slowly without the lower back arching.', ru: 'Лёжа на спине, согнутые колени над тазом. Напрягите пресс и подкручивайте таз к рёбрам силой пресса, а не махом ног, затем медленно опускайте, не прогибая поясницу.' },
  'pallof-press': { sec: ['shoulders'], en: 'Stand side-on to the cable, handle at the chest. Brace the abs and press the arms straight out without letting the torso rotate or the lower back arch, then do both sides.', ru: 'Встаньте боком к блоку, рукоять у груди. Напрягите пресс и выжимайте руки вперёд, не давая корпусу развернуться, а пояснице прогнуться, и выполните на обе стороны.' },
  'hollow-hold': { sec: [], en: 'Lie on your back, arms overhead, legs lifted low, lower back pressed into the floor. Brace the abs, breathe steadily and raise the legs higher if the back starts to lift.', ru: 'Лёжа на спине, руки за головой, ноги приподняты невысоко, поясница прижата к полу. Напрягите пресс, дышите ровно, а если поясница отрывается, поднимите ноги выше.' },
  'bird-dog': { sec: ['back', 'glutes'], en: 'On all fours, brace the abs and reach one arm and the opposite leg out long. Keep the hips level and the lower back from sagging, pause, then switch sides.', ru: 'Встаньте на четвереньки, напрягите пресс и вытягивайте разноимённые руку и ногу. Таз ровный, поясница не провисает, пауза, затем смените сторону и повторите.' },
  'mountain-climber': { sec: ['shoulders', 'quads'], en: 'High plank with the hands under the shoulders and the abs braced. Drive the knees towards the chest one at a time, hips level, breathing steadily and never letting the lower back sag.', ru: 'Упор лёжа, ладони под плечами, пресс напряжён. Поочерёдно подтягивайте колени к груди, таз на уровне плеч, дышите ровно и не проваливайтесь в пояснице.' },
  'v-up': { sec: ['quads'], en: 'Lie flat with the arms overhead and brace the abs. Lift arms and legs together to meet above the hips, lower with control, and bend the knees if the lower back starts to arch.', ru: 'Лёжа на спине, руки за головой, пресс напряжён. Одновременно поднимайте руки и ноги навстречу друг другу, подконтрольно опускайте, а если поясница прогибается, согните колени.' },
  'toes-to-bar': { sec: ['forearms', 'back'], en: 'Hang from the bar with active shoulders and brace the abs. Curl the pelvis up to bring the toes to the bar and lower slowly, with no kipping and no arching of the lower back.', ru: 'Вис на перекладине, плечи активны, пресс напряжён. Подкручивайте таз, поднимая носки к перекладине, и медленно опускайте, без раскачки и без прогиба в пояснице.' },
  'db-side-bend': { sec: [], en: 'Stand tall, dumbbell in one hand, abs braced. Bend towards the weight and come back up with the opposite obliques, no twisting or lower-back arch, then do both sides.', ru: 'Стойте ровно, гантель в одной руке, пресс напряжён. Наклоняйтесь к гантели и возвращайтесь за счёт косых с другой стороны, не скручиваясь и не прогибаясь в пояснице, затем смените сторону.' },
  'roman-chair-side-bend': { sec: [], en: 'Lie sideways on the roman chair, hip on the pad, feet hooked, abs braced. Lower the torso sideways and lift with the obliques, lower back not arched, then do both sides.', ru: 'Лягте боком на римский стул, бедро на подушке, стопы зафиксированы, пресс напряжён. Опускайте корпус в сторону и поднимайтесь за счёт косых без прогиба в пояснице, затем смените сторону.' },
  'weighted-plank': { sec: ['shoulders'], en: 'Forearms under the shoulders, plate on the upper back, not the lower back. Brace the abs and squeeze the glutes so the lower back doesn\'t sag, and breathe steadily throughout.', ru: 'Предплечья под плечами, блин на верхней части спины, а не на пояснице. Напрягите пресс и ягодицы, чтобы поясница не провисала, и дышите ровно на протяжении всего подхода.' },
  'landmine-rotation': { sec: ['shoulders'], en: 'Hold the end of the bar at arm\'s length, feet wide, abs braced. Arc the bar from hip to hip by turning the torso and pivoting the feet, lower back neutral, working both sides.', ru: 'Держите конец грифа на вытянутых руках, ноги широко, пресс напряжён. Ведите гриф дугой от бедра к бедру, разворачивая корпус и стопы, поясница нейтральная, работайте в обе стороны.' },
  'ball-crunch': { sec: [], en: 'Lie back on the ball so it supports the lower back, feet wide on the floor. Brace and curl the ribs up, then return with control, without sinking into a lower-back arch.', ru: 'Лягте на фитбол так, чтобы он поддерживал поясницу, стопы широко на полу. Напрягите пресс, скручивайтесь вверх и подконтрольно возвращайтесь, не проваливаясь в прогиб в пояснице.' },
  'outdoor-walk': { sec: [], en: 'Walk tall with relaxed shoulders and a natural arm swing, rolling from heel to toe. Keep a brisk pace where you can still talk in full sentences.', ru: 'Идите прямо, плечи расслаблены, руки свободно двигаются, стопа перекатывается с пятки на носок. Держите бодрый темп, при котором ещё можно говорить полными фразами.' },
  'outdoor-run': { sec: [], en: 'Run tall with a slight forward lean, relaxed shoulders and short, quick steps landing under the hips. Most runs should feel easy, at a pace where you can still talk.', ru: 'Бегите прямо с лёгким наклоном вперёд, плечи расслаблены, шаг короткий и частый, стопа приземляется под тазом. Большинство пробежек в лёгком темпе, при котором можно разговаривать.' },
  'treadmill-run': { sec: [], en: 'Stay in the middle of the belt, run tall and keep your hands off the rails. Land softly under the hips and pick a pace where you can still speak in short sentences.', ru: 'Держитесь середины полотна, бегите прямо и не хватайтесь за поручни. Приземляйтесь мягко под таз и выбирайте темп, при котором можно говорить короткими фразами.' },
  'incline-walk': { sec: ['glutes', 'calves'], en: 'Walk tall with a slight lean from the ankles and let go of the rails, since holding on takes the work out of the incline. Keep a steady pace where you can still hold a conversation.', ru: 'Идите прямо с лёгким наклоном от голеностопа и отпустите поручни: если держаться, подъём теряет смысл. Темп ровный, такой, чтобы можно было поддерживать разговор.' },
  'jump-rope': { sec: ['calves'], en: 'Stay tall on the balls of the feet with small, quiet jumps. Turn the rope with the wrists, elbows close to the body, at a rhythm where your breathing stays steady.', ru: 'Корпус прямой, прыгайте на носках, невысоко и мягко. Вращайте скакалку кистями, локти у корпуса, держите ритм, в котором дыхание остаётся ровным.' },
  'air-bike': { sec: ['shoulders'], en: 'Set the seat so the knee stays slightly bent at the bottom, and sit tall. Push and pull the handles in time with the legs, starting easy because the fan resistance climbs fast.', ru: 'Выставьте сиденье так, чтобы колено внизу оставалось слегка согнутым, спина прямая. Толкайте и тяните рукояти в ритме ног и начинайте спокойно: сопротивление вентилятора растёт очень быстро.' },
  'outdoor-cycling': { sec: ['quads'], en: 'Set the saddle so the knee is slightly bent at the bottom of the stroke. Keep the upper body relaxed and ride at a pace where you can still talk, spinning rather than grinding.', ru: 'Выставьте седло так, чтобы колено в нижней точке оставалось слегка согнутым. Плечи расслаблены, темп такой, чтобы можно было разговаривать, крутите педали легко и часто, а не продавливайте их.' },
  'swimming': { sec: ['back', 'shoulders'], en: 'Keep the body long and flat near the surface, head in line with the spine. Exhale steadily into the water and swim at a relaxed pace you could keep going for a long time.', ru: 'Тело вытянуто и лежит на воде горизонтально, голова продолжает линию позвоночника. Ровно выдыхайте в воду и плывите в спокойном темпе, который можете держать долго.' },
  'sled-push': { sec: ['quads', 'glutes', 'calves'], en: 'Hands on the poles, body leaning in a straight line from head to heel, back flat. Drive with short, powerful steps and pick a load you can keep moving steadily without stalling.', ru: 'Руки на стойках, корпус в наклоне одной линией от головы до пяток, спина ровная. Толкайте короткими мощными шагами и берите вес, который можно двигать ровно, без остановок.' },
  'skierg': { sec: ['back', 'triceps', 'core'], en: 'Stand tall with the arms high, then pull the handles down by hinging at the hips and bracing the abs until the hands pass the thighs. Rise smoothly at a rhythm you can breathe with.', ru: 'Встаньте прямо, руки вверху, и тяните рукояти вниз, сгибаясь в тазобедренных и напрягая пресс, пока кисти не дойдут до бёдер. Плавно выпрямляйтесь в ритме, при котором дыхание не сбивается.' },
};
